def maximum_product(nums):
    import heapq
    max_heap, min_heap = [], []
    for num in nums:
        heapq.heappush(max_heap, -heapq.heappushpop(min_heap, num))
        if len(max_heap) > 3:
            heapq.heappop(max_heap)
        if len(min_heap) > 3:
            heapq.heappop(min_heap)
    return -max_heap[0] * min_heap[0] * (max_heap[0] if len(max_heap) == 3 else min_heap[0])
[Done]

