def no_of_subsequences(arr, k):
    n = len(arr)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j]
            if arr[i - 1] < j:
                dp[i][j] += dp[i - 1][j - arr[i - 1]]

    return sum(dp[n])

