def pancake_sort(arr):
    for i in range(len(arr)):
        max_idx = find_max(arr, i)
        if max_idx != i:
            arr = flip(arr, 0, max_idx) if max_idx != len(arr) - 1 else arr
            arr = flip(arr, 0, len(arr) - 1)
    return arr

def find_max(arr, start):
    max_idx = start
    for i in range(start, len(arr)):
        if arr[i] > arr[max_idx]:
            max_idx = i
    return max_idx

def flip(arr, a, b):
    return arr[:a] + arr[a:b+1][::-1] + arr[b+1:]

