def min_Ops(arr, k, target):
    if len(arr) < k:
        return -1
    total = sum(arr)
    if total % k != 0:
        return -1
    avg = total // k
    if max(arr) > avg:
        return -1
    return sum([max(0, avg - x) for x in arr])

