def find_length(s, k):
    max_diff = 0
    for i in range(len(s)):
        count_0 = count_1 = 0
        for j in range(i, len(s)):
            if s[j] == '0':
                count_0 += 1
            else:
                count_1 += 1
            if j - i + 1 == k:
                max_diff = max(max_diff, abs(count_0 - count_1))
                if count_0 > count_1:
                    count_0 -= 1
                else:
                    count_1 -= 1
    return max_diff
